SELECT split_part(c.path, ' > ', 1) AS dept, SUM(oi.quantity) AS u FROM order_items oi JOIN product_variants v USING (variant_id) JOIN products p USING (product_id) JOIN categories c ON c.category_id = p.category_id WHERE oi.order_id IN (SELECT order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2026-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-04-01 00:00:00') GROUP BY 1 ORDER BY u DESC LIMIT 3
